"""Create/drop only databases generated by this fixture, never the supplied DB."""

import os
from pathlib import Path
from uuid import uuid4

import psycopg
import pytest
from alembic import command
from alembic.config import Config
from psycopg import sql
from psycopg.conninfo import conninfo_to_dict, make_conninfo
from sqlalchemy import create_engine
from sqlalchemy.pool import NullPool

ROOT = Path(__file__).resolve().parents[2]


@pytest.fixture(scope="session")
def test_admin():
    dsn = os.environ.get("BADGER_TEST_ADMIN_DSN")
    if not dsn:
        pytest.skip("Set BADGER_TEST_ADMIN_DSN to an isolated local PostgreSQL server.")
    parameters = conninfo_to_dict(dsn)
    if parameters.get("dbname") != "postgres" or parameters.get("host") not in (
        "127.0.0.1",
        "localhost",
        "::1",
    ):
        pytest.fail(
            "Test admin DSN must use localhost and the postgres maintenance DB."
        )
    with psycopg.connect(dsn, autocommit=True, connect_timeout=5) as connection:
        yield connection, dsn


@pytest.fixture
def empty_database(test_admin):
    admin, dsn = test_admin
    name = "badger_test_" + uuid4().hex
    # Never use IF NOT EXISTS or accept a caller-specified test database name.
    # Cleanup becomes eligible only after our CREATE DATABASE actually succeeds.
    admin.execute(
        sql.SQL("CREATE DATABASE {} TEMPLATE template0").format(sql.Identifier(name))
    )
    try:
        yield make_conninfo(dsn, dbname=name)
    finally:
        admin.execute(sql.SQL("DROP DATABASE {}").format(sql.Identifier(name)))


def migrate(dsn, revision="head", *, downgrade=False):
    engine = create_engine(
        "postgresql+psycopg://",
        creator=lambda: psycopg.connect(dsn),
        poolclass=NullPool,
    )
    try:
        with engine.begin() as connection:
            config = Config(str(ROOT / "alembic.ini"))
            config.attributes["connection"] = connection
            if downgrade:
                command.downgrade(config, revision)
            else:
                command.upgrade(config, revision)
    finally:
        engine.dispose()


@pytest.fixture
def database(empty_database):
    migrate(empty_database)
    return empty_database


@pytest.fixture
def connection(database):
    with psycopg.connect(
        database, autocommit=True, options="-c timezone=UTC -c statement_timeout=5000"
    ) as connection:
        yield connection
